import pytest
import torch
import torch_npu
import omni_custom_ops
from torch_npu.testing.testcase import TestCase, run_tests


def golden_scatter_block_update(input_tensor, indices, updates):
    """CPU单标杆: input[indices[k,0], indices[k,1], :] = updates[k, :]"""
    output = input_tensor.clone()
    for k in range(indices.shape[0]):
        idx0 = indices[k, 0].item()
        idx1 = indices[k, 1].item()
        output[idx0, idx1, :] = updates[k, :]
    return output


def make_noncontig_dim0(tensor, pad=128):
    """构造第0维非连续的tensor (通过as_strided, dim0 stride增加pad个元素)"""
    b_n, b_s, D = tensor.shape
    stride_0 = b_s * D + pad
    base = torch.zeros(b_n, stride_0, dtype=tensor.dtype, device=tensor.device)
    view = torch.as_strided(base, size=(b_n, b_s, D), stride=(stride_0, D, 1))
    view.copy_(tensor)
    return view


def run_scatter_block_update(b_n, b_s, D, T, dtype, indices_dtype=torch.int32,
                             noncontig=False, pad=128):
    """执行一次scatter_block_update并与CPU标杆做二进制一致比较"""
    torch.manual_seed(42)

    # 构造input
    if dtype == torch.int8:
        input_cpu = torch.randint(-128, 127, (b_n, b_s, D), dtype=dtype)
    else:
        input_cpu = torch.randn(b_n, b_s, D, dtype=dtype)

    # 构造indices: (T, 2), 范围 [0, b_n) x [0, b_s)
    flat_indices = torch.randperm(b_n * b_s)[:T]
    idx0 = (flat_indices // b_s).to(indices_dtype)
    idx1 = (flat_indices % b_s).to(indices_dtype)
    indices = torch.stack([idx0, idx1], dim=1)

    # 构造updates: (T, D)
    if dtype == torch.int8:
        updates = torch.randint(-128, 127, (T, D), dtype=dtype)
    else:
        updates = torch.randn(T, D, dtype=dtype)

    # CPU golden
    golden_output = golden_scatter_block_update(input_cpu, indices, updates)

    # NPU执行 (原地版本)
    input_npu = input_cpu.npu()
    if noncontig:
        input_npu = make_noncontig_dim0(input_npu, pad=pad)
    else:
        input_npu = input_npu.clone()
    indices_npu = indices.npu()
    updates_npu = updates.npu()

    torch.ops.custom.npu_ai_infra_scatter_block_update_(input_npu, indices_npu, updates_npu)

    # 二进制一致比较
    npu_output = input_npu.cpu()
    if not torch.equal(golden_output, npu_output):
        max_diff = (golden_output.float() - npu_output.float()).abs().max().item()
        mismatch = (golden_output != npu_output).sum().item()
        total = golden_output.numel()
        pytest.fail(
            f"Binary mismatch! shape=({b_n},{b_s},{D}), T={T}, dtype={dtype}, "
            f"noncontig={noncontig}, max_diff={max_diff}, "
            f"mismatch_elements={mismatch}/{total}"
        )


# ======================== 连续tensor测试 ========================
class TestCustomAiInfraScatterBlockUpdate(TestCase):
    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_bf16_base(self):
        """BF16 基础case: (8192, 128, 128), T=8192"""
        run_scatter_block_update(b_n=8192, b_s=128, D=128, T=8192, dtype=torch.bfloat16)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_fp16_base(self):
        """FP16 基础case: (4096, 64, 64), T=4096"""
        run_scatter_block_update(b_n=4096, b_s=64, D=64, T=4096, dtype=torch.float16)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_fp32_base(self):
        """FP32 基础case: (1024, 32, 32), T=1024"""
        run_scatter_block_update(b_n=1024, b_s=32, D=32, T=1024, dtype=torch.float32)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_int8_base(self):
        """INT8 基础case: (2048, 64, 128), T=2048"""
        run_scatter_block_update(b_n=2048, b_s=64, D=128, T=2048, dtype=torch.int8)


    # ======================== D非32B对齐测试 ========================

    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_bf16_D_not_aligned(self):
        """BF16 D=100, D*sizeof(BF16)=200 非32B对齐"""
        run_scatter_block_update(b_n=512, b_s=32, D=100, T=512, dtype=torch.bfloat16)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_fp32_D_not_aligned(self):
        """FP32 D=7, D*sizeof(FP32)=28 非32B对齐"""
        run_scatter_block_update(b_n=256, b_s=16, D=7, T=256, dtype=torch.float32)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_fp16_D_not_aligned(self):
        """FP16 D=3, D*sizeof(FP16)=6 非32B对齐"""
        run_scatter_block_update(b_n=256, b_s=16, D=3, T=256, dtype=torch.float16)


    # ======================== D=1 特殊路径测试 ========================

    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_bf16_D1(self):
        """BF16 D=1 (走TBuf中转路径)"""
        run_scatter_block_update(b_n=1024, b_s=64, D=1, T=1024, dtype=torch.bfloat16)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_fp32_D1(self):
        """FP32 D=1"""
        run_scatter_block_update(b_n=512, b_s=32, D=1, T=512, dtype=torch.float32)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_fp16_D1(self):
        """FP16 D=1"""
        run_scatter_block_update(b_n=512, b_s=32, D=1, T=512, dtype=torch.float16)


    # ======================== 非连续tensor测试 (dim0 stride != b_s*D) ========================

    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_noncontig_bf16_base(self):
        """BF16 非连续: (8192, 128, 128), pad=128"""
        run_scatter_block_update(b_n=8192, b_s=128, D=128, T=8192,
                                dtype=torch.bfloat16, noncontig=True, pad=128)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_noncontig_fp16_D_not_aligned(self):
        """FP16 非连续 + D非对齐: D=50, pad=64"""
        run_scatter_block_update(b_n=512, b_s=32, D=50, T=512,
                                dtype=torch.float16, noncontig=True, pad=64)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_noncontig_fp32_D1(self):
        """FP32 非连续 + D=1, pad=32"""
        run_scatter_block_update(b_n=256, b_s=16, D=1, T=256,
                                dtype=torch.float32, noncontig=True, pad=32)


    # ======================== INT64 indices测试 ========================

    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_contig_bf16_int64_indices(self):
        """BF16 + INT64 indices"""
        run_scatter_block_update(b_n=1024, b_s=64, D=128, T=1024,
                                dtype=torch.bfloat16, indices_dtype=torch.int64)


    # ======================== 边界case测试 ========================

    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_T1_single_update(self):
        """T=1 只更新一行"""
        run_scatter_block_update(b_n=64, b_s=16, D=32, T=1, dtype=torch.bfloat16)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_small_shape(self):
        """最小shape: b_n=1, b_s=1, D=1, T=1"""
        run_scatter_block_update(b_n=1, b_s=1, D=1, T=1, dtype=torch.float32)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_D_max_256(self):
        """D=256 最大值"""
        run_scatter_block_update(b_n=256, b_s=16, D=256, T=256, dtype=torch.bfloat16)


    @pytest.mark.filterwarnings("ignore::DeprecationWarning")
    @pytest.mark.resources(device="npu:*", npus_per_node=1)
    def test_large_T(self):
        """大T: T=65536"""
        run_scatter_block_update(b_n=1024, b_s=64, D=64, T=65536, dtype=torch.bfloat16)
